class WordDictionary {
    struct Node {
        Node* next[26] = {nullptr};
        bool word = false;
    };
    Node* root;

    bool match(Node* n, const string& w, size_t i) {
        if (!n) return false;
        if (i == w.size()) return n->word;
        if (w[i] != '.') return match(n->next[w[i] - 'a'], w, i + 1);
        for (Node* child : n->next) {  // a dot tries every branch
            if (child && match(child, w, i + 1)) return true;
        }
        return false;
    }
public:
    WordDictionary() { root = new Node(); }

    void addWord(string word) {
        Node* n = root;
        for (char c : word) {
            if (!n->next[c - 'a']) n->next[c - 'a'] = new Node();
            n = n->next[c - 'a'];
        }
        n->word = true;
    }

    bool search(string word) { return match(root, word, 0); }
};

class WordDictionary {
    // Words grouped by length; a search scans same-length words (independent of the C++ trie).
    private final Map<Integer, Set<String>> byLength = new HashMap<>();

    public WordDictionary() {
    }

    public void addWord(String word) {
        byLength.computeIfAbsent(word.length(), k -> new HashSet<>()).add(word);
    }

    public boolean search(String word) {
        Set<String> candidates = byLength.get(word.length());
        if (candidates == null) return false;
        if (word.indexOf('.') < 0) return candidates.contains(word);
        for (String c : candidates) {
            boolean ok = true;
            for (int i = 0; i < word.length() && ok; i++) {
                char p = word.charAt(i);
                if (p != '.' && p != c.charAt(i)) ok = false;
            }
            if (ok) return true;
        }
        return false;
    }
}
